pub fn entries() -> Vec<KernelRule> {
    vec![
        KernelRule {
            rule_id: "pipeline-cache-key-covers-every-function-constant".to_string(),
            gpu_concept: "When ONE kernel source is compiled into N variants via driver function constants (Metal `[[function_constant(N)]]`), the KERNEL-PIPELINE CACHE KEY must include EVERY bound constant -- a key naming a SUBSET of the bound constants serves one variant's compiled binary for another's launch arguments, which is SILENT WRONG MATH (the specialized binary reads a constant the key never discriminated), not a perf miss. The defect ships in the natural authoring order: the first specialization binds one constant and the key names it; the SECOND bound constant is added later and the key extension is exactly the step that is forgotten -- so the rule is 'every time a function constant is added, the cache-key format string changes in the same commit'. The sentinel convention must stay coherent with the key too: a sentinel constant value (the source: 0) means 'keep the generic runtime-dispatch variant', so sentinel and non-sentinel launches MUST NOT share a key entry, and a constant value OUTSIDE the known set must REFUSE the dispatch fail-closed (the source: `type >= 40u -> return 0`), never clamp to the nearest variant. Kernel side, each function constant is read with a fallback to the runtime arg (`constant ? constant : args.field`) so the generic variant remains the semantic baseline. Suggest-only fix class (a cache-key format extension + a bind-time range refuse; a parse-only proposer cannot see which constants a driver binds). Regime: driver-specialized kernel variants selected per launch (quant-format specialization, tile specialization) behind any keyed pipeline cache. Gain SOURCE-REPORTED (M3 Ultra, MoE mm: 8192-token fresh prefix 1218.64 -> 1242.95 tok/s (+1.99%), append 1204.41 -> 1226.98 (+1.87%); decode hamlet 51.48 -> 53.14 (+3.2%); correctness = the source's 36-case harness compares generic/specialized/generic gate-up + down outputs BIT FOR BIT across six formats). Honest NotBenchable here (no Metal toolchain in the bench harness; foreign silicon). Distinct from proven-shape-static-sibling-identical-results-fallback (a fixed SHAPE baked into a hand-written sibling with a dispatch ladder; this bakes a TYPE TAG via driver function constants on ONE source, and the defect axis is cache-key COMPLETENESS, which that rule does not own), from enum-dispatch-separate-kernel-per-variant (separate kernel FUNCTIONS per host enum; here ONE source the driver recompiles per constant), and from hardcoded-fast-path-jit-specialization (the WHICH-kernel axis; this is the WHICH-COMPILED-BINARY axis). Source: ivanfioravanti/ds4-metal @ b85a6174 (MIT) -- commits 38d3e45 'Optimize Qwen prefill with quantization-specialized MoE kernels' (introduced the key WITHOUT the tail term) + b4c3550 'Improve Qwen Q2 decode geometry and partial prefill tiles' (added function constant 905 and HAD to extend the key -- the defect-first lesson in-repo): the constant decl (metal/qwen4.metal:2102-2104) '/* Zero retains runtime dispatch; a bound quantization removes the other dequantizers without changing the tile arithmetic. */ constant uint qwen4_moe_weight_type [[function_constant(900)]];'; the fallback read (metal/qwen4.metal:2312) 'const uint type = qwen4_moe_weight_type ? qwen4_moe_weight_type : args.weight_type;'; the host key + refuse (ds4_metal.m:47570-47581) 'const uint32_t type = specialize ? ((const qwen4_moe_mm_args *)args)->weight_type : 0u; if (type >= 40u) return 0; ... NSString *key = [NSString stringWithFormat:@\"%s_type=%u_tail=%u\", qwen4_kernel_names[kernel], type, tail_base];'. Batch 129 / Plan 110 / Research 151. RIDER (Batch 139 external instance, ivanfioravanti/ds4-metal @ 18ca8ec MIT -- commit fc6b023, ds4_metal.m:2615-2640 + :47691-47703): the DETECTION half of this defect class -- a failed pipeline lookup is memoized as an NSNull sentinel in the same cache (the error prints ONCE per name, not per dispatch: 'Failed lookups are remembered as NSNull so the error prints once per name instead of on every dispatch'), and the Qwen dispatch layer adds a once-guarded (static flag) diagnostic that names the DEPLOYMENT failure mode, not just the missing symbol: Metal sources are compiled from ./metal in the WORKING DIRECTORY at startup, so a newer binary run from an older checkout compiles stale sources and silently misses the new kernels ('Run from the matching checkout, update metal/, or point DS4_METAL_QWEN4_SOURCE at a current qwen4.metal'). Found via an 82d0314 binary run from a b4c3550 checkout: every MTP draft dispatch failed and speculation silently degraded to 28 tok/s. Two honest limits recorded in-source: the dispatch failure itself still no-ops (log-once without fail-loud leaves throughput degraded if nobody reads stderr), and the failure sentinel must be a DISTINCT cache value (NSNull, not nil) so a later successful compile of the same name can replace it.".to_string(),
            ref_shape: "// one kernel source, two bound function constants, a cache key\n// naming only the FIRST: the second variant's binary is served for\n// launches whose constant binds differ ONLY in the unnamed constant.\nfn pipeline(device: &Device, wt: u32, tail: u32) -> Pipeline {\n    let key = format!(\"qwen4_moe_mm_type={wt}\"); // tail_base MISSING\n    cache.get_or_compile(device, &key, |d| compile(d, wt, tail))\n}\n".to_string(),
            opt_pattern: "// the key carries EVERY bound constant; sentinel stays distinct;\n// out-of-range binds refuse instead of clamping to a neighbor variant.\nfn pipeline(device: &Device, wt: u32, tail: u32) -> Option<Pipeline> {\n    if wt >= 40 {\n        return None; // fail-closed: unknown quant tag never binds\n    }\n    // 0 = the generic runtime-dispatch variant -- its own key entry\n    let key = format!(\"qwen4_moe_mm_type={wt}_tail={tail}\");\n    Some(cache.get_or_compile(device, &key, |d| compile(d, wt, tail)))\n}\n".to_string(),
        },
        KernelRule {
            rule_id: "block-quant-weight-pad-never-extends-activations".to_string(),
            gpu_concept: "When a block-quantized weight format forces BLOCK-GRANULAR row widths (Q2_K = 256) and the logical width is not a multiple of the block (the source: 640 = 2.5 blocks), the padding lives on the WEIGHT ROW STRIDE ONLY -- activations stay at LOGICAL width and every dequant block/loop is gated by the logical bound, because the padded weight tail has NO corresponding activation element to read: reading one is out-of-bounds, not merely wasted work. The three load-bearing halves: (1) host layout computes the weight stride from the padded dim while every consumer-facing dim stays logical; (2) the dequant loop guards per element-group against the logical bound (the source: `if (ib * 256u + group * 16u + l >= in_dim) continue;`) instead of iterating the padded block count; (3) dispatch VALIDATION rejects activation widths that would split a dequant group across the boundary fail-closed (the source rejects `F + 1u` -- a partial activation group) instead of clamping. Test discipline carries the rule: conformance fixtures fill the padding with NONZERO values so a kernel that reads the physical tail fails loudly (zeros would hide the defect), and an aligned-format control proves the padding path itself costs no throughput. Suggest-only fix class (a stride formula, a loop guard, a bind-time reject; a parse-only proposer cannot see which dim is padded). Regime: block-quantized weight layouts (Q2_K and kin) whose logical dims are not block multiples. Gain SOURCE-REPORTED (M3 Ultra: 5.16 GiB (11%) memory saved with decode 47.63 -> 47.31 tok/s and prefill 962.72 -> 973.17 tok/s -- under-1% deltas comparable to run variation; the honest tradeoff is recorded in-source: BF16 top-token agreement 91.33% -> 90.32% from the padded recipe). Honest NotBenchable here. Distinct from sparse-kv-index-list-sentinel-padded (sentinel padding of INDEX lists to a tile multiple; this is FORMAT-IMPOSED weight-stride padding where the pad must never be READ), from pad-tail-to-fixed-tile (pads the WORK tail up into a resident tile for dispatch avoidance -- here the pad exists for STORAGE granularity and must stay semantically invisible), from alignment-gated-zero-copy-view (alignment enables zero-copy; this is alignment the format forces on one operand only), and from stride-align-vectorization-key (vectorization alignment chosen for speed; this is block-granularity forced by the quant format). Source: ivanfioravanti/ds4-metal @ b85a6174 (MIT) -- commit 5bd8796 'Support padded Q2_K down projections for Qwen3.8': the loop guard (metal/qwen4.metal:1759, 1763-1764) 'const uint nb = (in_dim + 255u) / 256u;' ... '/* Padded Q2_K down weights have no corresponding activation tail. */ if (ib * 256u + group * 16u + l >= in_dim) continue;'; the host stride (ds4_metal.m:48444, decode twin :48282) 'const uint32_t weight_dim = weight_type == 10u ? (ff_dim + 255u) / 256u * 256u : ff_dim;'; the layout contract (ds4.c:5389-5390) '/* Q2_K down rows store 640 logical inputs in three 256-value blocks. * Activations remain 640 wide; only the weight row stride is padded. */'; the test discipline (tests/test_qwen4_kernels.c:1237) '/* Nonzero random padding ensures kernels ignore the physical tail. */' + the fail-closed reject (:1338-1340) 'require_ok(!ds4_gpu_qwen4_moe_down_tensor(..., F + 1u, E, 0, UINT32_MAX), \"Q2_K down rejects a partial activation group\");'. Batch 129 / Plan 110 / Research 151.".to_string(),
            ref_shape: "// the padded width LEAKS into the activation loop: the kernel reads\n// the weight tail as if activation elements existed past in_dim.\nfn down_proj(w: &[Block], a: &[f32], out: &mut [f32]) {\n    let nb = w.len(); // 3 blocks for a 640-wide input (768 stored)\n    for b in 0..nb {\n        for l in 0..256 {\n            let x = a[b * 256 + l]; // OOB READ: a has only 640 elements\n            acc += dequant(w[b], l) * x;\n        }\n    }\n}\n".to_string(),
            opt_pattern: "// weight stride is padded; activations stay logical; the dequant\n// loop is gated per element against the LOGICAL bound; partial groups\n// are rejected at bind time, not clamped.\nfn down_proj(w: &[Block], a: &[f32], out: &mut [f32]) -> Result<(), Bind> {\n    if a.len() % 256 != 0 && a.len() != logical_dim {\n        return Err(Bind::PartialActivationGroup); // fail-closed\n    }\n    let nb = (logical_dim + 255) / 256;\n    for b in 0..nb {\n        for l in 0..256 {\n            let i = b * 256 + l;\n            if i >= logical_dim { break; } // no activation tail exists\n            acc += dequant(w[b], l) * a[i];\n        }\n    }\n    Ok(())\n}\n".to_string(),
        },
        KernelRule {
            rule_id: "expert-remainder-routed-to-smaller-tile-twins".to_string(),
            gpu_concept: "When a per-bucket (per-expert) variable-length work list is tiled by a WIDE compiled tile, the partial tail tile burns (tile_width - remainder) ZERO-COLUMN matrix products on every small bucket -- the fix is a work PARTITION, not a runtime branch: the aligned prefix runs the widest tile twin, the remainder runs the smallest twin that covers it (the source's ladder: remainder <= 8 -> tile 8, <= 16 -> 16, <= 32 -> 32, else the full tile), with each variant's ownership decided by a COMPILE-TIME tail-base constant so no variant recomputes another's rows and the outputs stay disjoint (the wide variant truncates to `count - remainder` rows; the tail variant starts at `count - remainder` and returns unless its tile IS the chosen tail twin). The alternative the source measured and REJECTED is the runtime-branch skip inside one kernel: the branch slowed even the DISABLED control (branch presence costs the compiled kernel its register/tile schedule), and the specialized skipping variant still lost -10.98% -- 'the tail change was removed: saved arithmetic did not compensate for the resulting compiled kernel cost'. Thresholds (which batch sizes route to which twin) are device/format-shaped tuning; the PARTITION STRUCTURE is the rule. Bit-parity with the single-tile path is the regression gate (accumulation order per row is unchanged -- only which launch computes which rows moves). Suggest-only fix class (a work-partition preamble + a tail launch; a parse-only proposer cannot see the per-bucket length distribution). Regime: MoE / grouped-GEMM per-expert lists under wide compiled tiles. Gain SOURCE-REPORTED (M3 Ultra, Qwen Q2 MoE: 1000-token prefill 1079.32 -> 1112.54 tok/s (+3.08%), 7930-token 1247.37 -> 1263.13 (+1.26%), decode +1.90-2.07%; 192 teacher-forced full-vocabulary vectors bit-identical to the single-tile path). Honest NotBenchable here. Distinct from batch-width-routed-dual-tile-twins (supplies the twin MECHANISM routed by BATCH width; this routes by PER-LIST REMAINDER and composes with it -- twins first, then remainder routing), from pad-tail-to-fixed-tile (pads the tail UP for dispatch avoidance when the tail is NEAR-FULL; this splits DOWN when the remainder is SMALL -- the regime boundary is the remainder size), from extent-clamped-operand-views-partial-k-tile (clamps the K axis INSIDE one tile; this splits the M axis ACROSS launches), and from tail-simdgroup-cull-barriers-preserved (simdgroup-level culling within ONE launch; this is a launch-count split with disjoint ownership). Source: ivanfioravanti/ds4-metal @ b85a6174 (MIT) -- commit b4c3550 'Improve Qwen Q2 decode geometry and partial prefill tiles': the tile-twin selector (ds4_metal.m:48379-48386) '/* Low-bit experts receive few tokens in short prefills. Smaller token tiles avoid unused matrix products while retaining the same K order. */ ... if (n_tokens <= 512u) default_nt = 1u; else if (n_tokens <= 1024u) default_nt = 2u;'; the tails gate (:48396-48399) 'return nt > 1u && (override >= 0 ? override != 0 : (type == 16u || type == 10u) && ds4_gpu_device_name_contains(\"M3 Ultra\"));'; the kernel-side ownership ladder (metal/qwen4.metal:2388-2398) 'const uint remainder = count % qwen4_moe_tail_base; const uint tail_tt = remainder <= 8u ? 8u : remainder <= 16u ? 16u : remainder <= 32u ? 32u : 64u; if (TT < qwen4_moe_tail_base) { if (!remainder || tail_tt != TT) return; work_start = count - remainder; work_count = remainder; } else if (remainder && tail_tt < TT) { work_count = count - remainder; }'; the disjoint tail grid (ds4_metal.m:48432) 'const MTLSize tail_grid = MTLSizeMake((ff_dim + 31u) / 32u, n_expert, 1);'; the rejected alternative (38d3e45, qwen38-q2-round2 doc) 'A runtime branch slowed even the disabled control to 1056.45 tokens/s ... the skipping variant achieved only 1084.92 (-10.98%) ... The tail change was removed'. Batch 129 / Plan 110 / Research 151.".to_string(),
            ref_shape: "// every expert bucket is tiled by the ONE wide compiled tile: a\n// bucket of 7 rows pays a 64-wide tile -- 57 zero-column products.\nfn moe_mm(buckets: &[Vec<Row>], tile: usize) {\n    for list in buckets {\n        let tiles = list.len().div_ceil(tile);\n        for t in 0..tiles {\n            launch_wide_tile(&list[t * tile..], tile); // tail burns lanes\n        }\n    }\n}\n".to_string(),
            opt_pattern: "// prefix rows go to the wide twin; the remainder goes to the\n// smallest twin that covers it; compile-time tail_base keeps the\n// two launches' row ownership disjoint and the math bit-identical.\nfn moe_mm(buckets: &[Vec<Row>], tile: usize) {\n    for list in buckets {\n        let remainder = list.len() % tile;\n        let full = list.len() - remainder;\n        if full > 0 {\n            launch_tile(&list[..full], tile); // widest twin: aligned prefix\n        }\n        if remainder > 0 {\n            let twin = tail_twin(remainder); // 8 -> 16 -> 32 ladder\n            launch_tile(&list[full..], twin); // disjoint rows, same K order\n        }\n    }\n}\n".to_string(),
        },
        KernelRule {
            rule_id: "window-recurrence-halo-snapshot-block-parallel".to_string(),
            gpu_concept: "A per-channel RECURRENCE whose carried state is only the last K-1 RAW inputs (a causal conv, K <= 4) need not run one thread per channel over the whole token axis: SNAPSHOT each block's incoming K-1 window in a cheap pre-pass kernel, then run ALL token blocks concurrently with the tap order and FP32 accumulation unchanged -- the sequential chain is not re-associated away (no scan machinery needed for a window this short), it is made READ-ONLY. The load-bearing choice is SNAPSHOT SCOPE: the HALO only (K-1 rows per block), never the whole input -- the source measured the full-input snapshot variant at +1.53% and SUPERSEDED it with the halo snapshot at +2.10% (the full copy duplicates every byte the blocked body could have re-read from the original buffer, and the copy is the very serialization being removed). Ownership closes the loop: only the FINAL block writes the carried state (the source: `if (end == args.n_tokens) ... state[t * C + c] = win[t];`), so no block reads another block's overwritten input and the history semantics are bit-identical to the serial kernel. Gate the transform behind a batch-size floor and a scratch cap (the source: `total <= (1u << 28)` -- 15 MiB at 8K tokens, 1.875 MiB at 1K, capped at 1 GiB) with fallback to the original serial stream kernel. Suggest-only fix class (a pre-pass kernel + a blocked body + a host gate; a parse-only proposer cannot see the state-width-to-token-length ratio). Regime: short-window causal convolutions / sliding-window recurrences over long token axes. Gain SOURCE-REPORTED (M3 Ultra, Qwen Q2 GDN conv: halo +2.10% vs full-snapshot +1.53%; combined with the decode fusions: 8K prose 1300.48 -> 1338.80 tok/s, +2.95%). Honest NotBenchable here. Distinct from chunkwise-parallel-recurrence (chunks carry state SEQUENTIALLY chunk-to-chunk -- a chain remains; the halo snapshot removes the chain entirely for raw-input windows, converting the dependency into a read-only pre-pass), from fused-conv-state-shift-dot-silu (the serial fused stream kernel this parallelizes -- same family, the pre-change shape), from whole-sequence-zero-barrier-single-dispatch-scan (associative-scan machinery for full-sequence state; a K<=4 window needs only the halo, not a scan), and from first-order-affine-recurrence-associative-scan (scan-composable STATE recurrences; this is a raw-INPUT window where the state is a copy, not a fold). Source: ivanfioravanti/ds4-metal @ b85a6174 (MIT) -- commit b85a617 'Speed up Qwen prefill with reusable weights and block convolution': the scope comment (metal/qwen4.metal:385-386) '/* Only incoming block windows need a snapshot; raw rows inside each block stay private to its channel thread until they have entered the window. */'; the halo write (metal/qwen4.metal:395) 'halo[gid] = block == 0 ? state[t * C + c] : x[(uint64_t)(block * QWEN4_CONV_BLOCK - H + t) * C + c];'; the final-block state ownership (metal/qwen4.metal:418) 'if (end == args.n_tokens) for (uint t = 0; t + 1u < K; t++) state[t * C + c] = win[t];'; the host gate + kernel pair (ds4_metal.m:47805, 47808) 'if (total <= (1u << 28) && qwen4_prefill_reuse(n_tokens)) {' ... 'const char *names[] = {\"kernel_qwen4_conv_halo\", \"kernel_qwen4_conv_blocked\"};'. Batch 129 / Plan 110 / Research 151.".to_string(),
            ref_shape: "// one thread per channel walks EVERY token serially: the carried\n// window (last K-1 raw inputs) chains the whole axis.\nfn causal_conv(x: &[f32], state: &mut [f32; K_1], w: &[f32; K], out: &mut [f32]) {\n    for t in 0..x.len() {\n        let mut acc = 0.0;\n        for k in 0..K {\n            acc += window_at(x, state, t, k) * w[k];\n        }\n        out[t] = silu(acc);\n    }\n}\n".to_string(),
            opt_pattern: "// pre-pass snapshots each block's incoming K-1 halo; ALL blocks then\n// run in parallel; only the final block writes the carried state --\n// the serial chain became a read-only copy, tap order unchanged.\nfn causal_conv_blocked(x: &[f32], state: &mut [f32; K_1], w: &[f32; K], out: &mut [f32]) {\n    let halo = snapshot_halos(x, state); // K-1 rows per block, read-only\n    parallel_blocks(x, &halo, w, out, |end, win| {\n        if end == x.len() {\n            *state = *win; // ownership: the LAST block closes the chain\n        }\n    });\n}\n".to_string(),
        },
        KernelRule {
            rule_id: "fused-residual-update-writes-separate-next-buffer".to_string(),
            gpu_concept: "Fusing a stage that UPDATES a carried buffer (the residual combine) with the stage that READS it (the normalization) must NOT write in place: the fused kernel reads the old buffers READ-ONLY and writes DISTINCT next buffers (reusing an otherwise-idle existing allocation is fine -- the source carries a separate 512-bytes-per-token injection buffer so normalization chunks never read a slice another threadgroup is concurrently writing), the DISPATCH rejects aliased binds fail-closed (the source compares buffer identities and returns 0 on any match), and the HOST swaps the old/next pointers after the launch. The second half is scope honesty: a fusion validated at one session shape does not automatically extend to another -- the source enabled the same fusions in multi-token (MTP) sessions, measured 0.04-0.42% SLOWER, and restricted the fused path to ordinary single-token decode; the fused path is gated by the measured session shape, and the sibling shape keeps the unfused path. Exactness survives fusion: the normalization keeps its FP32 reductions and eps untouched (the source ships 192 full-vocabulary FP32 vectors byte-identical to the pre-fusion baseline). Suggest-only fix class (signature gains old/next pairs + an alias reject + a pointer swap + a shape gate; a parse-only proposer cannot see buffer lifetimes). Regime: fused residual+norm (or any read-carried-buffer + write-same-buffer) kernel pairs. Gain SOURCE-REPORTED (M3 Ultra, Qwen Q2 decode: +1.05-1.22%; MTP sessions measured 0.04-0.42% slower -> restricted; 192/192 vectors byte-identical). Honest NotBenchable here. Distinct from inplace-output-alias (the OPPOSITE direction: alias output onto input to SKIP an allocation within one pass when no other reader exists -- this rule forbids read-write aliasing ACROSS a fused boundary where other chunks read concurrently), from pool-buffer-aliasing-dedicated-output (sub-allocation pool hazard where input and output share one MTLBuffer across kernels; here the race is INSIDE one kernel between threadgroups), from role-scoped-store-must-match-compute-guard (a store writing the wrong ROLE's rows; this is a whole-buffer lifetime contract), and from bit-exact-dispatch-fusion-boundary-emulation (barrier semantics when emulating a fusion boundary; this is the buffer-ownership contract when actually fusing). Source: ivanfioravanti/ds4-metal @ b85a6174 (MIT) -- commit 82d0314 'Fuse Qwen ordinary decode projections and residual normalization': the kernel contract (metal/qwen4.metal:2802-2803) '/* Read the old residual and injection buffer; write separate next buffers. * Each normalization chunk writes only its own residual slice. */'; the alias reject (ds4_metal.m:47663-47664) 'if (ds4_gpu_tensor_buffer(next_R) == ds4_gpu_tensor_buffer(R) || ds4_gpu_tensor_buffer(inj_part) == ds4_gpu_tensor_buffer(old_inj)) return 0;'; the session-shape gate (ds4.c:55533) 'if (T == 1u && !g->mtp_R && DS4_N_HC == 4u && ds4_gpu_qwen4_decode_fusions_enabled() &&'; the injection buffer note (ds4.c:54851-54852) '/* A separate injection buffer keeps combined normalization race-free. */ ds4_gpu_tensor *inj_alt;'. Batch 129 / Plan 110 / Research 151.".to_string(),
            ref_shape: "// the fused kernel normalizes the residual IN PLACE: chunk A writes\n// the slice chunk B is still reading -- a cross-threadgroup race, and\n// the launch accepts aliased buffers silently.\nfn fused_rms_norm_in_place(r: &mut [f32], w: &[f32]) {\n    let inv = rsqrt(mean_sq(r) + eps);\n    for chunk in r.chunks_mut(CHUNK) {\n        threadgroup_spawn(|| {\n            for v in chunk {\n                *v = (*v * inv) * w; // reads and writes the same slice\n            }\n        });\n    }\n}\n".to_string(),
            opt_pattern: "// old buffers are read-only inputs; results land in distinct next\n// buffers; aliased binds are rejected at dispatch; the host swaps\n// pointers after; the fused path is gated to the measured shape.\nfn fused_rms_norm(old_r: &[f32], inj: &[f32], next_r: &mut [f32], w: &[f32]) -> Result<(), Bind> {\n    if buf_id(next_r) == buf_id(old_r) || buf_id(inj) == buf_id(old_inj()) {\n        return Err(Bind::Aliased); // fail-closed, never clamp\n    }\n    let inv = rsqrt(mean_sq(old_r) + eps); // FP32 reduction untouched\n    for (dst, (r, i)) in next_r.chunks_mut(CHUNK).zip(old_r.chunks(CHUNK).zip(inj.chunks(CHUNK))) {\n        for ((d, rv), iv) in dst.iter_mut().zip(r.iter().zip(i)) {\n            *d = ((rv + iv) * inv) * w; // separate next buffer per chunk\n        }\n    }\n    swap_pointers();\n    Ok(())\n}\n".to_string(),
        },
    ]
}
